// swift-tools-version: 6.0
import PackageDescription

// Header search paths for quoted cross-directory imports (SPM has no CocoaPods header maps).
// Generated by `yarn generate-spm-header-paths`; `yarn lint-ios` fails when it is out of date.
let headerSearchPaths: [String] = [
    "ios",
    "ios/core/common",
    "ios/core/containers/common",
    "ios/core/containers/split",
    "ios/core/containers/stack/container",
    "ios/core/containers/stack/header",
    "ios/core/containers/stack/screen",
    "ios/core/containers/tabs",
    "ios/core/containers/tabs/bottom-accessory",
    "ios/core/containers/tabs/container",
    "ios/core/containers/tabs/screen",
    "ios/core/modals/contained-modal",
    "ios/core/modals/form-sheet",
    "ios/core/scroll-view",
    "ios/core/utils",
    "ios/core/views/scroll-to-top-guard",
    "ios/legacy",
    "ios/legacy/events",
    "ios/legacy/integrations",
    "ios/legacy/utils",
    "ios/react",
    "ios/react/bridging",
    "ios/react/containers/split",
    "ios/react/containers/split/conversion",
    "ios/react/containers/stack/conversion",
    "ios/react/containers/stack/header",
    "ios/react/containers/stack/host",
    "ios/react/containers/stack/screen",
    "ios/react/containers/tabs",
    "ios/react/containers/tabs/bottom-accessory",
    "ios/react/containers/tabs/conversion",
    "ios/react/containers/tabs/extensions",
    "ios/react/containers/tabs/host",
    "ios/react/containers/tabs/screen",
    "ios/react/conversion",
    "ios/react/helpers/container",
    "ios/react/helpers/image",
    "ios/react/modals/contained-modal",
    "ios/react/modals/form-sheet",
    "ios/react/modals/form-sheet/conversion",
    "ios/react/utils",
    "ios/react/utils/extensions",
    "ios/react/views/safe-area",
    "ios/react/views/scroll-to-top-guard",
    "ios/react/views/scroll-view-marker",
    "ios/react/views/scroll-view-marker/conversion",
    "common/cpp",
    "cpp/legacy",
]

// Every top-level entry that is not a source root. SwiftPM walks the whole target `path` ("."),
// so in a `link:`-ed checkout it would otherwise crawl node_modules, the example apps and the
// symlinks that lead back here on every package resolution.
// Generated by `yarn generate-spm-excluded-paths`; `yarn lint-ios` fails when it is out of date.
let excludedPaths: [String] = [
    "FabricExample",
    "TVOSExample",
    "android",
    "apps",
    "docs",
    "experimental",
    "gesture-handler",
    "guides",
    "ios/RNScreens.xcodeproj",
    "lib",
    "node_modules",
    "private",
    "react-navigation",
    "reanimated",
    "scripts",
    "src",
    "windows",
]

let cSettings: [CSetting] = headerSearchPaths.map { .headerSearchPath($0) }

let cxxSettings: [CXXSetting] = [
    .define("DEBUG", .when(configuration: .debug)),
    .define("NDEBUG", .when(configuration: .release)),
] + headerSearchPaths.map { .headerSearchPath($0) }

let package = Package(
    name: "RNScreens",
    platforms: [.iOS("15.1")],
    products: [
        .library(name: "RNScreens", targets: ["RNScreens"]),
    ],
    dependencies: [
        // Resolved from the autolinker symlink `<app>/ios/build/generated/autolinking/libs/RNScreens`,
        // not from node_modules: `../../../../xcframeworks` -> `<app>/ios/build/xcframeworks`,
        // `../../../ios` -> `<app>/ios/build/generated/ios`. Same layout `npx react-native spm scaffold` emits.
        // Making this self-contained (remote RN package URL + shipping our own codegen output) is blocked
        // on RN publishing a remote SPM package and would require `codegenConfig.includesGeneratedCode`, see:
        // https://github.com/react/react-native/blob/v0.87.1/packages/react-native/scripts/spm/__docs__/spm-header-paths-contract.md#hand-authored-community-library-contract
        .package(name: "ReactNative", path: "../../../../xcframeworks"),
        .package(name: "React-GeneratedCode", path: "../../../ios"),
    ],
    targets: [
        .target(
            name: "RNScreens",
            dependencies: [
                .product(name: "ReactHeaders", package: "ReactNative"),
                .product(name: "ReactNativeHeaders", package: "ReactNative"),
                .product(name: "ReactNativeDependenciesHeaders", package: "ReactNative"),
                .product(name: "ReactAppHeaders", package: "React-GeneratedCode"),
            ],
            path: ".",
            exclude: excludedPaths,
            sources: ["ios", "common/cpp", "cpp"],
            publicHeadersPath: "ios",
            cSettings: cSettings,
            cxxSettings: cxxSettings,
            linkerSettings: [
                .linkedFramework("UIKit"),
                .linkedFramework("Foundation"),
            ]
        ),
    ],
    cxxLanguageStandard: .cxx20
)
